        <h2 class = "popUp__text">Вход</h2>
        <form @submit.prevent="handleLogin" novalidate>
          <div class="form-group">
            <label class = "form-group__text" for="email">Email:</label>
            <input
              class = "form-group__input"
              type="email"
              id="email"
              v-model="email"
              placeholder="Введите ваш email"
              required
              @input="onInput"
              @blur="onBlur"
            />
            <div v-if="showHint" class="form-group__hint" :class="{ show: showHint }">
              Пожалуйста, введите корректный email (требуется символ @).
            </div>
          </div>
          <div class="form-group">
            <label class = "form-group__text" for="password">Пароль:</label>
            <input
              class = "form-group__input"
              type="password"
              id="password"
              v-model="password"
              placeholder="Введите ваш пароль"
              required
            />
          </div>
          <button type="submit" class="popUp__btn-login btn">Войти</button>
        </form>
        <button class="popUp__btn-register btn" @click="handleRegister">Регистрация</button>
      </div>
    </div>
  </template>
  
  <script>
  export default {
    data() {
      return {
        email: "",
        password: "",
        showEmailError: false, 
      };
    },
    methods: {
      onInput() {
      if (this.timeoutId) {
        clearTimeout(this.timeoutId);
      }
      this.timeoutId = setTimeout(() => {
        this.showHint = !this.email.includes('@');
      }, 200); 
    },
    onBlur() {
      this.showHint = !this.email.includes('@');
    },
      handleLogin() {
        
        if (!this.email.includes('@')) {
          this.showEmailError = true; 
          return;
        }
        console.log("Вход с email:", this.email);
        this.closePopup();
      },
      handleRegister() {
        this.closePopup();
        this.$router.push({ name: "registration" });
      },
      closePopup() {
        this.$emit("close");
      },
    },
  };
  </script>
  
